#!/usr/bin/env python3
"""Apply script: recognize "Validated Claims" as a paid status in
Portfolio Analysis (a newer claims export template uses this wording
instead of "Paid Claims").

Run from the HealthCross repo root: python3 apply_validated_claims_status_fix.py
"""
import base64, hashlib, os, sys

MARKER = "VALIDATED_CLAIMS_STATUS_FIX_2026_08_04"

FILES = [
    {
        'path': 'app/scoring/rules/portfolio_analysis.py',
        'sha256': '534d62b664d4831815d82e6807991e20ae6d4c5df40fff7d23b1be1890848078',
        'size': 20463,
        'b64': '',
    },
    {
        'path': 'tests/test_portfolio_analysis.py',
        'sha256': 'd329dc37a385520ff5bb9b8d327dd10bf1a1ed6a18f27696f741c3297d5ee3ee',
        'size': 29034,
        'b64': '',
    },
]


def main():
    repo_root = os.getcwd()
    ok = True
    for entry in FILES:
        path = os.path.join(repo_root, entry['path'])
        data = base64.b64decode(entry['b64'])
        if len(data) != entry['size']:
            print(f"SIZE MISMATCH before write: {entry['path']}")
            ok = False
            continue
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'wb') as f:
            f.write(data)
        with open(path, 'rb') as f:
            written = f.read()
        actual_sha = hashlib.sha256(written).hexdigest()
        if actual_sha == entry['sha256']:
            print(f"OK  {entry['path']}  ({len(written)} bytes, sha256={actual_sha[:12]}...)")
        else:
            print(f"CHECKSUM MISMATCH  {entry['path']}  expected={entry['sha256'][:12]}... actual={actual_sha[:12]}...")
            ok = False
    if ok:
        print(f"\nAll files written and verified. Marker: {MARKER}")
        print("Next: python3 -m pytest -q   (should show 447 passed)")
        print("Then: git add -A && git commit -m '...' && git push")
        print("Also: re-upload your Claims export in Portfolio Analysis after this to")
        print("recompute paid/outstanding with the fixed classification.")
    else:
        print("\nSOME FILES FAILED TO VERIFY - do not commit. Re-run this script once more first.")
        sys.exit(1)


if __name__ == '__main__':
    main()
